  "    return !!(track && track.device && track.device.engine === 'sampler');",
  "  }",
  "",
  "  function kindText(track) {",
  "    if (isAudioTrack(track)) return 'audio';",
  "    if (isSamplerTrack(track)) return 'sampler';",
  "    return (track && track.device && track.device.type) || 'instrument';",
