  "  function fourCc(view8, at) {",
  "    var tag = '';",
  "    for (var i = 0; i < 4; i += 1) tag += String.fromCharCode(view8.getUint8(at + i));",
  "    return tag;",
  "  }",
  "",
  "  // The client's own WAV reader: 16- and 24-bit PCM, the two shapes the",
  "  // gateway writes. Nothing here calls decodeAudioData (the parity rule), so a",
  "  // take sounds the same in the panel and in a render.",
  "  function decodeWavBytes(buffer) {",
  "    if (!buffer || typeof buffer.byteLength !== 'number' || buffer.byteLength < 44) {",
  "      throw new Error('That take is not a WAV file.');",
  "    }",
  "    var view8 = new DataView(buffer);",
  "    if (fourCc(view8, 0) !== 'RIFF' || fourCc(view8, 8) !== 'WAVE') {",
  "      throw new Error('That take is not a WAV file.');",
  "    }",
  "    var rate = 0;",
  "    var channels = 0;",
  "    var bits = 0;",
  "    var format = 0;",
  "    var dataAt = -1;",
  "    var dataBytes = 0;",
  "    var at = 12;",
  "    while (at + 8 <= view8.byteLength) {",
  "      var id = fourCc(view8, at);",
  "      var size = view8.getUint32(at + 4, true);",
  "      var body = at + 8;",
  "      if (id === 'fmt ') {",
  "        format = view8.getUint16(body, true);",
  "        channels = view8.getUint16(body + 2, true);",
  "        rate = view8.getUint32(body + 4, true);",
  "        bits = view8.getUint16(body + 14, true);",
  "      } else if (id === 'data') {",
  "        dataAt = body;",
  "        dataBytes = Math.min(size, Math.max(0, view8.byteLength - body));",
  "        break;",
  "      }",
  "      at = body + size + (size % 2);",
