  "",
  "  // The gateway's own refusal for a sample that would hold too many samples",
  "  // (takes-upload.js's capRefusal), so an import refused before it starts says",
  "  // exactly what the upload would have said.",
  "  function sampleCapText(actual) {",
  "    return 'A sample can be at most ' + String(SAMPLE_MAX_SECONDS) + ' s ('",
