  "        })",
  "          .then(function (response) {",
  "            return response.json().then(function (body) { return { status: response.status, body: body }; });",
  "          })",
  "          .then(function (result) {",
  "            if (result.status !== 200 || !result.body || !result.body.song_id) {",
  "              throw new Error((result.body && result.body.error) || 'The song could not be created.');",
  "            }",
  "            window.location.href = '/dashboard/studio?song=' + encodeURIComponent(result.body.song_id);",
  "          })",
  "          .catch(function (err) { toast(errorText(err)); });",
  "      });",
  "    }",
  "",
  "    load();",
  "",
  "    // The library holds no socket, no engine and no document, so it has",
  "    // nothing to tear down and is always safe to leave alone.",
  "    return { alive: function () { return true; }, teardown: function () {} };",
  "  }",
  "",
