  "",
  "    // The handle boot() keeps on the page element, so a second boot over a",
  "    // live session does nothing and a teardown can retire exactly this one.",
  "    var session = {",
  "      alive: function () { return !view.closed; },",
  "      teardown: teardown",
  "    };",
  "",
  "    // The view this song was last left in, when this browser keeps the choice",
  "    // (a browser that refuses storage starts in Session, and the switch still",
