  "      catch (err) { return SESSION_VIEW; }",
  "      return value === ARRANGEMENT_VIEW ? ARRANGEMENT_VIEW : SESSION_VIEW;",
  "    }",
  "",
  "    function storeMode(songId, mode) {",
