  "      var out = {};",
  "      for (var key in value) {",
  "        if (!Object.prototype.hasOwnProperty.call(value, key)) continue;",
  "        if (key === '_index' || key === '_after' || key === '_before') continue;",
  "        out[key] = value[key];",
  "      }",
  "      return out;",
  "    }",
  "",
  "    function snapshot() {",
  "      if (!view.doc) return EMPTY;",
