  "      if (!song || typeof song !== 'object') return EMPTY;",
  "      var tracks = Array.isArray(song.tracks) ? song.tracks.map(clean) : [];",
  "      var scenes = Array.isArray(song.scenes) ? song.scenes.map(clean) : [];",
