  "        var entry = entries[i] || {};",
  "        var refs = Array.isArray(entry.touched) ? entry.touched : [];",
  "        var kind = entry.author && entry.author.kind === 'human' ? 'human' : 'agent';",
  "        for (var r = 0; r < refs.length; r += 1) {",
  "          if (String(refs[r]).indexOf('placement:') !== 0) continue;",
