  "      renderSampler(snap);",
  "      renderHistory();",
  "      renderPresence();",
  "      renderRecordings();",
  "      renderRecordingState();",
  "      var serialized = JSON.stringify({",
  "        meta: snap.meta, tracks: snap.tracks, scenes: snap.scenes, clips: snap.clips,",
  "        takes: snap.takes, samples: snap.samples, slices: snap.slices, banks: snap.banks,",
  "        pads: snap.pads, patterns: snap.patterns, steps: snap.steps, arrangement: snap.arrangement",
  "      });",
