  "      clear(gridHost);",
  "",
  "      var columns = 'minmax(196px, 232px)';",
  "      for (var t = 0; t < snap.tracks.length; t += 1) columns += ' 164px';",
  "      gridHost.style.gridTemplateColumns = columns;",
  "",
  "      var corner = el('div', 'st-corner');",
  "      corner.appendChild(button('st-btn', '+ Track', { 'data-act': 'add-track', title: 'Add an instrument track' }));",
  "      corner.appendChild(button('st-btn', '+ Audio track', { 'data-act': 'add-audio-track', title: 'Add a track for recorded takes' }));",
  "      corner.appendChild(button('st-btn', '+ Sampler', { 'data-act': 'add-sampler-track', title: 'Add a track that plays a kit of pads' }));",
  "      corner.appendChild(button('st-btn', '+ Scene', { 'data-act': 'add-scene', title: 'Add a scene row' }));",
