  "      ensureEngine()",
  "        .then(function (engine) {",
  "          return engine.calibrate({ input: entry.stream, latencyHint: view.latencyHint, sinkId: view.sinkId || undefined });",
  "        })",
  "        .then(function (result) {",
  "          var record = {",
  "            latency_frames: Math.max(0, Math.round(Number(result && result.latency_frames) || 0)),",
  "            rate: Number(result && result.rate) || (view.ctx ? Number(view.ctx.sampleRate) : 0),",
  "            spread_frames: Math.max(0, Math.round(Number(result && result.spread_frames) || 0)),",
  "            measured_at: new Date().toISOString()",
