  "          var key = latencyKey(trackId);",
  "          if (key) view.latency[key] = record;",
  "          var save = key ? storeCall('putLatency', [key, record]) : Promise.resolve(null);",
  "          return save.catch(function () { return null; }).then(function () {",
  "            var ms = latencyMs(record);",
  "            var spread = record.rate > 0 ? Math.round((record.spread_frames / record.rate) * 1000) : 0;",
  "            status.textContent = String(ms === null ? 0 : ms) + ' ms (\u00b1' + String(spread) + ' ms)';",
  "            render();",
