  "    }",
  "",
  "    // ---- the audio track header ------------------------------------------",
  "",
  "    function audioPanel(track) {",
  "      var box = el('div', 'st-audio');",
  "      var entry = view.armed[track.id] || null;",
  "",
  "      var row = el('div', 'st-th-btns');",
  "      row.appendChild(button('st-toggle st-arm' + (entry ? ' st-on' : ''), entry ? 'Armed' : 'Arm', {",
  "        'data-act': 'arm-audio',",
  "        'data-track-id': track.id,",
  "        title: entry ? 'Disarm this track' : 'Arm this track so Record records into it'",
  "      }));",
  "      box.appendChild(row);",
  "",
  "      var select = el('select', 'st-select st-input');",
  "      select.setAttribute('data-act', 'audio-input');",
  "      select.setAttribute('data-track-id', track.id);",
  "      select.setAttribute('aria-label', 'Input for ' + String(track.name));",
  "      var inputs = Array.isArray(view.inputs.list) ? view.inputs.list : [];",
  "      var empty = el('option', '', inputs.length ? 'Choose an input' : 'No inputs found');",
  "      empty.value = '';",
  "      select.appendChild(empty);",
  "      var known = false;",
  "      for (var i = 0; i < inputs.length; i += 1) {",
  "        var option = el('option', '', inputs[i].label || ('Input ' + String(i + 1)));",
  "        option.value = inputs[i].device_id;",
  "        if (entry && entry.device_id === inputs[i].device_id) { option.selected = true; known = true; }",
  "        select.appendChild(option);",
  "      }",
  "      if (entry && !known && entry.device_id) {",
  "        // A device the enumeration no longer lists (it was unplugged) is still",
  "        // the one the arm names, so the picker keeps saying which it is.",
  "        var current = el('option', '', entry.label);",
  "        current.value = entry.device_id;",
  "        current.selected = true;",
  "        select.appendChild(current);",
  "      }",
  "      box.appendChild(select);",
  "",
  "      var channels = el('select', 'st-select st-channels');",
  "      channels.setAttribute('data-act', 'audio-channels');",
  "      channels.setAttribute('data-track-id', track.id);",
  "      channels.setAttribute('aria-label', 'Channels for ' + String(track.name));",
  "      for (var count = 1; count <= 2; count += 1) {",
  "        var channelOption = el('option', '', count === 1 ? '1 channel' : '2 channels');",
  "        channelOption.value = String(count);",
  "        if ((entry ? entry.channels : 2) === count) channelOption.selected = true;",
  "        channels.appendChild(channelOption);",
  "      }",
  "      box.appendChild(channels);",
  "",
  "      var key = latencyKey(track.id);",
  "      var record = latencyRecord(track.id);",
  "      var latencyRow = el('div', 'st-th-btns');",
  "      var chip = null;",
  "      if (record) {",
  "        chip = el('span', 'st-latchip', latencyText(record));",
  "        latencyRow.appendChild(chip);",
  "        latencyRow.appendChild(button('st-btn st-small', 'Calibrate\u2026', { 'data-act': 'calibrate', 'data-track-id': track.id }));",
  "      } else {",
  "        chip = button('st-btn st-small st-latchip', NOT_CALIBRATED_CHIP, { 'data-act': 'calibrate', 'data-track-id': track.id });",
  "        latencyRow.appendChild(chip);",
  "      }",
  "      chip.setAttribute('data-role', 'latency');",
  "      if (key) chip.setAttribute('data-latency-key', key);",
  "      box.appendChild(latencyRow);",
  "",
  "      var on = view.monitor.on && view.monitor.track_id === track.id;",
  "      box.appendChild(button('st-toggle' + (on ? ' st-on' : ''), 'Monitor through Studio', {",
  "        'data-act': 'monitor', 'data-track-id': track.id,",
  "        title: 'Send your input through Studio, so you hear it late'",
  "      }));",
  "      if (on) {",
  "        var warning = el('p', 'st-warn', monitorSentence(view.monitor.latency));",
  "        warning.setAttribute('data-role', 'monitor-warning');",
  "        box.appendChild(warning);",
  "      }",
  "      return box;",
  "    }",
  "",
  "    // ---- starting, keeping and ending a take ------------------------------",
  "",
  "    function engineNowFrame() {",
  "      if (!view.ctx) return 0;",
  "      return Math.round(Number(view.ctx.currentTime) * Number(view.ctx.sampleRate));",
  "    }",
  "",
  "    // The notices above the transport: the warnings a take needs, kept until",
  "    // the next recording starts.",
  "    function showNotice(text) {",
