  "      if (value && view.notices.indexOf(value) < 0) view.notices.push(value);",
  "      renderNotices();",
  "    }",
  "",
  "    function clearNotices() {",
  "      view.notices = [];",
  "      renderNotices();",
  "    }",
  "",
  "    function renderNotices() {",
  "      if (view.closed) return;",
  "      var host = page.querySelector('[data-role=rec-notice]');",
  "      if (!host) return;",
  "      host.textContent = view.notices.join(' ');",
  "      host.hidden = view.notices.length === 0;",
  "    }",
  "",
  "    // Which loop pass the take is in now, on the same clock it is armed on.",
  "    function currentPass(rec) {",
  "      if (!rec || !rec.active || !rec.loop_frames) return 1;",
  "      var elapsed = engineNowFrame() - rec.arm_frame - rec.offset_frames;",
  "      if (elapsed < 0) return 1;",
  "      return Math.max(1, Math.floor(elapsed / rec.loop_frames) + 1);",
  "    }",
  "",
  "    function renderRecordingState() {",
  "      if (view.closed) return;",
  "      var status = page.querySelector('[data-role=rec-status]');",
  "      var record = page.querySelector('[data-act=record]');",
  "      var armed = armedList(snapshot()).length;",
  "      if (record) {",
  "        record.disabled = !!view.rec || armed === 0;",
  "        record.setAttribute('title', armed === 0 ? 'Arm an audio track first' : 'Record into the armed track');",
  "      }",
  "      if (!status) return;",
  "      if (!view.rec) {",
  "        status.hidden = true;",
  "        status.textContent = '';",
  "        status.removeAttribute('data-passes');",
  "        status.removeAttribute('data-recording');",
  "        status.removeAttribute('data-ready');",
  "        return;",
  "      }",
