  "      var entry = view.armed[track.id];",
  "      var bpm = Number(snap.meta && snap.meta.bpm) || 120;",
  "      var rate = 0;",
  "      clearNotices();",
  "      // The raw-input warning is a property of the input, not of a moment: it",
  "      // comes back after every clear while that input is still processed.",
