  "      // recorder is still being built is remembered, not lost.",
  "      var rec = {",
  "        track_id: track.id,",
  "        channels: entry.channels,",
  "        rate: rate || 48000,",
  "        bpm: bpm,",
  "        offset_frames: 0,",
  "        compensated: false,",
  "        recorder: null,",
  "        ready: false,",
  "        launch: null,",
  "        takes: [],",
  "        clip_id: null,",
  "        scene_id: null,",
  "        length_bars: 0,",
  "        arm_frame: 0,",
  "        loop_frames: 0,",
  "        active: false,",
