  "",
  "    // A launch report names the scene and the frame a take starts on.",
  "    function armFromLaunch(launch) {",
  "      var rec = view.rec;",
  "      if (!rec || rec.active) return;",
  "      var sceneId = launch && launch.scene_id ? String(launch.scene_id) : '';",
