  "      } else {",
  "        send('clip.add_audio', {",
  "          clip_id: clipId,",
  "          track_id: rec.track_id,",
  "          scene_id: sceneId,",
  "          length_bars: bars,",
  "          name: track ? track.name : 'Audio'",
  "        });",
  "      }",
  "      rec.clip_id = clipId;",
