  "        clip_id: rec.clip_id,",
  "        rate: rec.rate,",
  "        channels: rec.channels,",
  "        offset_frames: rec.offset_frames,",
  "        compensated: rec.compensated,",
  "        bpm: rec.bpm,",
  "        chunk_count: null,",
  "        begun: false,",
  "        finished: false,",
  "        created_at: new Date().toISOString()",
