  "",
  "    function onTakeChunk(segment, index, bytes) {",
  "      var rec = view.rec;",
  "      if (!rec) return;",
  "      var number = Number(segment) || 0;",
  "      var at = Number(index) || 0;",
  "      // The first chunk of the next pass means this pass is over: its chunks",
  "      // all arrived, in order, so it is counted, saved and sent now.",
  "      if (at === 0 && number > 0) finalizeTake(rec, rec.takes[number - 1]);",
  "      var take = takeForSegment(rec, number);",
  "      if (!take) return;",
