  "      delete view.hashes[pending.take_id];",
  "      delete view.uploadAttempts[pending.take_id];",
  "      clearRetryTimer(pending.take_id);",
  "      renderRecordings();",
  "      return storeCall('deletePending', [pending.take_id]).then(function () { return 'done'; }, function () { return 'done'; });",
  "    }",
  "",
  "    function sendChunks(pending, have) {",
  "      return localHashes(pending).then(function (hashes) {",
  "        var chain = Promise.resolve();",
  "        hashes.forEach(function (entry) {",
  "          chain = chain.then(function () {",
  "            if (have[entry.index] === entry.sha256) { return null; }",
  "            return storeCall('getChunk', [pending.take_id, entry.index]).then(function (bytes) {",
  "              if (!bytes) return missingChunk(pending);",
  "              return apiChunk(pending.take_id, entry.index, bytes).then(function () {",
