  "",
  "    // The count shown on a row is the number of indexes the gateway has",
  "    // confirmed: the ones its status named, plus each accepted chunk it lacked.",
  "    // A chunk that was already there is not counted twice, and the count never",
  "    // passes the take's own chunk count.",
  "    function setConfirmed(pending, received) {",
  "      var map = {};",
  "      for (var i = 0; i < received.length; i += 1) {",
  "        var entry = received[i] || {};",
  "        map[String(Number(entry.index))] = true;",
  "      }",
  "      pending.confirmed = map;",
  "      pending.uploaded = confirmedCount(pending);",
  "    }",
  "",
  "    function confirmedCount(pending) {",
