  "      pending.confirmed[String(Number(index))] = true;",
  "      pending.uploaded = confirmedCount(pending);",
  "      renderRecordings();",
  "    }",
  "",
  "    // A chunk this device no longer has. If its pending row is gone too, another",
  "    // view finished the take and there is nothing left to do; if the row is still",
  "    // here, a piece of the take really is missing.",
  "    function missingChunk(pending) {",
  "      return storeCall('getPending', [pending.take_id]).then(function (row) {",
  "        if (row) throw new Error('A piece of the take is missing from this device.');",
  "        throw VANISHED;",
  "      }, function () {",
  "        throw new Error('A piece of the take is missing from this device.');",
  "      });",
  "    }",
  "",
  "    // Every chunk's SHA-256, in index order: the list finish is given, and the",
  "    // way a resumed upload knows which chunks the gateway already holds.",
  "    function localHashes(pending) {",
  "      if (view.hashes[pending.take_id]) return Promise.resolve(view.hashes[pending.take_id]);",
  "      var count = Number(pending.chunk_count) || 0;",
  "      var list = [];",
  "      var chain = Promise.resolve();",
  "      for (var index = 0; index < count; index += 1) {",
  "        (function (at) {",
  "          chain = chain.then(function () {",
  "            return storeCall('getChunk', [pending.take_id, at]).then(function (bytes) {",
  "              if (!bytes) return missingChunk(pending);",
  "              return sha256Hex(bytes).then(function (sha) { list.push({ index: at, sha256: sha }); });",
  "            });",
  "          });",
  "        })(index);",
  "      }",
  "      return chain.then(function () {",
