  "        return list;",
  "      });",
  "    }",
  "",
  "    function scheduleUploadRetry(pending) {",
  "      if (view.closed) return;",
  "      clearRetryTimer(pending.take_id);",
  "      var attempts = Number(view.uploadAttempts[pending.take_id] || 0);",
  "      view.uploadAttempts[pending.take_id] = attempts + 1;",
  "      var wait = UPLOAD_RETRY_MS[Math.min(attempts, UPLOAD_RETRY_MS.length - 1)];",
  "      view.retryTimers[pending.take_id] = setTimeout(function () {",
  "        delete view.retryTimers[pending.take_id];",
  "        if (view.closed || pending.finished === true || pending.failed) return;",
  "        view.pendingTakes[pending.take_id] = pending;",
  "        renderRecordings();",
  "        uploadTake(pending);",
  "      }, wait);",
  "    }",
  "",
  "    function clearRetryTimer(takeId) {",
