  "        delete view.uploadAttempts[id];",
  "        uploadTake(pending);",
  "      }",
  "    }",
  "",
  "    function studioHeaders(json) {",
  "      var headers = {};",
  "      if (json) headers['content-type'] = 'application/json';",
  "      // The same CSRF header every other mutating fetch in this panel sends.",
  "      var token = cookie('crow_csrf');",
  "      if (token) headers['x-crow-csrf'] = token;",
  "      return headers;",
  "    }",
  "",
  "    function readJson(response) {",
  "      return response.json().catch(function () { return {}; }).then(function (body) {",
  "        if (!response.ok) {",
  "          var error = new Error((body && body.error) || 'Studio refused that upload.');",
  "          error.status = response.status;",
  "          throw error;",
  "        }",
  "        return body;",
  "      });",
  "    }",
  "",
  "    function apiStatus(takeId) {",
  "      return fetch(TAKE_API + '/' + encodeURIComponent(takeId), { credentials: 'same-origin' })",
  "        .then(function (response) {",
  "          if (response.status === 404) return null;",
  "          return readJson(response);",
  "        });",
  "    }",
  "",
  "    function apiBegin(pending) {",
  "      return projectIdFor().then(function (projectId) {",
  "        if (!Number.isInteger(projectId)) {",
  "          throw new Error('This song is not in a project this page can see.');",
  "        }",
  "        return fetch(TAKE_API + '/' + encodeURIComponent(pending.take_id), {",
  "          method: 'PUT',",
  "          credentials: 'same-origin',",
  "          headers: studioHeaders(true),",
  "          body: JSON.stringify(beginBody(pending, projectId))",
  "        }).then(readJson);",
  "      });",
  "    }",
  "",
  "    // What begin is told: a take's clip and its timing, or a sample's kind, its",
  "    // name, where it came from and the pad it is for. The two kinds share the",
  "    // same four routes and the same staging; only these details differ.",
  "    function beginBody(pending, projectId) {",
  "      if (pending.kind === 'sample') {",
  "        return {",
  "          kind: 'sample',",
  "          song_id: pending.song_id,",
  "          project_id: projectId,",
  "          name: pending.name,",
  "          origin: pending.origin,",
  "          target: pending.target || null,",
  "          rate: pending.rate,",
  "          channels: pending.channels",
  "        };",
  "      }",
  "      return {",
  "        song_id: pending.song_id,",
  "        project_id: projectId,",
  "        clip_id: pending.clip_id,",
  "        rate: pending.rate,",
  "        channels: pending.channels,",
  "        offset_frames: pending.offset_frames,",
  "        compensated: pending.compensated === true,",
  "        bpm: pending.bpm",
  "      };",
  "    }",
  "",
  "    // The song's project id, from the hub's own song list: the one read the",
  "    // library page already makes, and the only place this page can learn it.",
  "    function projectIdFor() {",
  "      if (Number.isInteger(view.projectId)) return Promise.resolve(view.projectId);",
  "      if (view.projectLookup) return view.projectLookup;",
  "      var pendingLookup = fetch('/api/studio/songs', { credentials: 'same-origin' })",
  "        .then(function (response) { return response.ok ? response.json() : []; })",
  "        .then(function (songs) {",
  "          view.projectLookup = null;",
