  "            var row = list[i] || {};",
  "            if (String(row.id) !== activeSongId) continue;",
  "            var projectId = Number(row.project_id);",
  "            if (Number.isInteger(projectId)) view.projectId = projectId;",
  "          }",
  "          return Number.isInteger(view.projectId) ? view.projectId : null;",
  "        })",
  "        .catch(function () {",
  "          view.projectLookup = null;",
  "          return null;",
  "        });",
  "      view.projectLookup = pendingLookup;",
  "      return pendingLookup;",
  "    }",
  "",
  "    function apiChunk(takeId, index, bytes) {",
  "      var headers = studioHeaders(false);",
