  "      }).then(readJson);",
  "    }",
  "",
  "    // On reload, the takes this device still owes are offered again: what the",
  "    // gateway lacks is sent, and one whose chunks all arrived is finished. A row",
  "    // with no chunk count is a recording the tab never finished, and its chunks",
  "    // are still here: they become a take, because they are audio the operator",
  "    // played.",
  "    function resumePending() {",
  "      storeCall('listPending', [])",
  "        .then(function (rows) {",
  "          var list = Array.isArray(rows) ? rows : [];",
  "          for (var i = 0; i < list.length; i += 1) {",
  "            var pending = list[i];",
  "            if (!pending || pending.song_id !== activeSongId) continue;",
  "            if (pending.finished === true) continue;",
  "            view.pendingTakes[pending.take_id] = pending;",
