  "",
  "    // ---- the timeline -----------------------------------------------------",
  "    //",
  "    // The approved design (mockups artboard 5): the header switch chooses",
  "    // between the session grid and the song laid out on bars, and the timeline",
  "    // is a ruler (a section row, the markers, the bar numbers) over one lane",
  "    // per track. A placement is a block in its track colour, outlined in the",
  "    // colour of whoever put it there (the operator is amber, an agent blue),",
  "    // and the white playhead follows the engine in arrangement mode.",
  "    //",
  "    // Every edit is one command per pointer release and snaps to whole bars (a",
  "    // fade to a quarter of a beat): place, move, resize, set_fades, split,",
  "    // remove, the markers and sections of the ruler, and ONE",
  "    // arrangement.record_performance for a whole recorded performance.",
  "",
  "    // The three maps of a snapshot's arrangement, whatever the snapshot says.",
  "    function arrangementOf(snap) {",
  "      var out = { placements: {}, markers: {}, sections: {} };",
  "      var raw = snap && snap.arrangement && typeof snap.arrangement === 'object' ? snap.arrangement : null;",
  "      if (!raw) return out;",
  "      var keys = ['placements', 'markers', 'sections'];",
  "      for (var k = 0; k < keys.length; k += 1) {",
  "        var key = keys[k];",
  "        var map = raw[key] && typeof raw[key] === 'object' ? raw[key] : {};",
  "        var list = {};",
  "        for (var id in map) {",
  "          if (!Object.prototype.hasOwnProperty.call(map, id)) continue;",
  "          var item = clean(map[id]);",
  "          if (item && typeof item === 'object') list[id] = item;",
  "        }",
  "        out[key] = list;",
  "      }",
  "      return out;",
  "    }",
  "",
  "    function objectList(map) {",
  "      var list = [];",
  "      for (var id in map) {",
  "        if (!Object.prototype.hasOwnProperty.call(map, id)) continue;",
  "        var item = map[id];",
  "        if (item && typeof item === 'object') list.push(item);",
  "      }",
  "      return list;",
  "    }",
  "",
  "    function placementList(snap) {",
  "      var list = objectList(arrangementOf(snap).placements);",
  "      list.sort(function (a, b) { return Number(a.start_bar) - Number(b.start_bar); });",
  "      return list;",
  "    }",
  "",
  "    function markerList(snap) {",
  "      var list = objectList(arrangementOf(snap).markers);",
  "      list.sort(function (a, b) { return Number(a.bar) - Number(b.bar); });",
  "      return list;",
  "    }",
  "",
  "    function sectionList(snap) {",
  "      var list = objectList(arrangementOf(snap).sections);",
