  "      var previous = view.mode;",
  "      view.mode = mode;",
  "      storeMode(activeSongId, mode);",
  "      // The engine may not exist yet: a new one is handed the view this song",
  "      // was left in by ensureEngine.",
  "      if (view.engine) {",
  "        try { view.engine.setMode(mode); } catch (err) { toast(errorText(err)); }",
  "      }",
  "      // A real switch into the timeline starts it at bar 0, as the sequencer",
