  "    }",
  "",
  "    // ---- the sampler: the pad-and-steps view ------------------------------",
  "    //",
  "    // A sampler track's clip is a pattern, so opening one opens this view",
  "    // instead of the piano roll (the approved design, mockup screen 2): the",
  "    // kit's bank tabs and their sixteen pads, a pad's own settings, and the",
  "    // ways a sound gets into a pad. Auditioning is local (a live trigger,",
  "    // never a history step); the chop editor draws the sample's waveform with a",
  "    // marker per slice start, and the steps are the selected pad's lane of the",
  "    // pattern being shown, sixteen to a page.",
  "",
  "    /** The banks of one kit, in the kit's own order. */",
  "    function banksOfTrack(snap, trackId) {",
  "      var list = [];",
  "      var banks = snap && snap.banks && typeof snap.banks === 'object' ? snap.banks : {};",
  "      for (var key in banks) {",
  "        if (!Object.prototype.hasOwnProperty.call(banks, key)) continue;",
  "        var bank = banks[key];",
  "        if (!bank || String(bank.track_id) !== String(trackId)) continue;",
  "        list.push(bank);",
  "      }",
  "      list.sort(function (a, b) { return (Number(a.order) || 0) - (Number(b.order) || 0); });",
  "      return list;",
  "    }",
  "",
  "    function bankOf(snap, trackId, bankId) {",
  "      var list = banksOfTrack(snap, trackId);",
  "      for (var i = 0; i < list.length; i += 1) {",
  "        if (String(list[i].id) === String(bankId)) return list[i];",
  "      }",
  "      return null;",
  "    }",
  "",
  "    /** One bank's pads, by their index. */",
  "    function padsOfBank(snap, trackId, bankId) {",
  "      var out = [];",
  "      var pads = snap && snap.pads && typeof snap.pads === 'object' ? snap.pads : {};",
  "      for (var key in pads) {",
  "        if (!Object.prototype.hasOwnProperty.call(pads, key)) continue;",
  "        var pad = pads[key];",
  "        if (!pad) continue;",
  "        if (String(pad.track_id) !== String(trackId)) continue;",
  "        if (String(pad.bank_id) !== String(bankId)) continue;",
  "        out.push(pad);",
  "      }",
  "      out.sort(function (a, b) { return (Number(a.index) || 0) - (Number(b.index) || 0); });",
  "      return out;",
  "    }",
  "",
  "    function padOf(snap, trackId, bankId, index) {",
  "      var list = padsOfBank(snap, trackId, bankId);",
  "      for (var i = 0; i < list.length; i += 1) {",
  "        if (Number(list[i].index) === Number(index)) return list[i];",
  "      }",
  "      return null;",
  "    }",
  "",
  "    function sampleOf(snap, sampleId) {",
  "      var samples = snap && snap.samples && typeof snap.samples === 'object' ? snap.samples : {};",
  "      var id = sampleId ? String(sampleId) : '';",
  "      if (!id || !Object.prototype.hasOwnProperty.call(samples, id)) return null;",
  "      return samples[id] || null;",
  "    }",
  "",
  "    /** The A01 label of one pad: its bank's letter and its own number. */",
  "    function padLabel(bank, index) {",
  "      var letter = 'A';",
  "      var name = String(bank && bank.name ? bank.name : '');",
  "      if (name) {",
  "        var first = name.charAt(0).toUpperCase();",
  "        if (first >= 'A' && first <= 'Z') letter = first;",
  "      }",
  "      var number = String(Number(index) + 1);",
  "      while (number.length < 2) number = '0' + number;",
  "      return letter + number;",
  "    }",
  "",
  "    /** What a pad is called: its own name, else its slice's or sample's, else Empty. */",
  "    function padName(snap, pad) {",
  "      var own = pad && pad.name ? String(pad.name) : '';",
  "      if (own) return own;",
  "      var sample = sampleOf(snap, pad ? pad.sample_id : '');",
  "      if (!sample) return 'Empty';",
  "      var name = String(sample.name || 'Sample');",
  "      var sliceId = pad && pad.slice_id ? String(pad.slice_id) : '';",
  "      if (!sliceId) return name;",
  "      var slices = snap && snap.slices && typeof snap.slices === 'object' ? snap.slices : {};",
  "      var list = [];",
  "      for (var key in slices) {",
  "        if (!Object.prototype.hasOwnProperty.call(slices, key)) continue;",
  "        var slice = slices[key];",
  "        if (!slice || String(slice.sample_id) !== String(sample.id)) continue;",
  "        list.push(slice);",
  "      }",
  "      list.sort(function (a, b) { return (Number(a.start_frame) || 0) - (Number(b.start_frame) || 0); });",
  "      for (var i = 0; i < list.length; i += 1) {",
  "        if (String(list[i].id) !== sliceId) continue;",
  "        return name + ' slice ' + String(i + 1);",
  "      }",
  "      return name;",
  "    }",
  "",
  "    /** The pending sample upload this device owes one pad, or null. */",
  "    function pendingForPad(trackId, bankId, index) {",
  "      for (var id in view.pendingTakes) {",
  "        if (!Object.prototype.hasOwnProperty.call(view.pendingTakes, id)) continue;",
  "        var pending = view.pendingTakes[id];",
  "        if (!pending || pending.kind !== 'sample') continue;",
  "        if (pending.finished === true || pending.failed) continue;",
  "        var target = pending.target;",
  "        if (!target || typeof target !== 'object') continue;",
  "        if (String(target.track_id) !== String(trackId)) continue;",
  "        if (String(target.bank_id) !== String(bankId)) continue;",
  "        if (Number(target.index) !== Number(index)) continue;",
  "        return pending;",
  "      }",
  "      return null;",
  "    }",
  "",
  "    function padPendingText(pending) {",
  "      return pending && pending.begun === true ? UPLOADING_PAD_TEXT : SAVED_LOCAL_TEXT;",
  "    }",
  "",
  "    /** The pattern clip the view is open on, or null. */",
  "    function patternClipOf(snap) {",
  "      var clip = view.selectedClipId ? snap.clips[view.selectedClipId] : null;",
  "      return clip && clip.kind === 'pattern' ? clip : null;",
  "    }",
  "",
  "    /** The kit the view is showing: its track and the bank the operator picked. */",
  "    function shownKit(snap) {",
  "      var clip = patternClipOf(snap);",
