  "      return box;",
  "    }",
  "",
  "    function padSettings(snap, track, bank, pad, index) {",
  "      var panel = el('div', 'st-pad-settings');",
  "      panel.appendChild(el('h3', 'st-pad-title',",
  "        pad && bank ? 'Pad ' + padLabel(bank, index) + ' \u00b7 ' + padName(snap, pad) : 'Pad'));",
  "      if (!pad || !bank) {",
  "        panel.appendChild(el('p', 'st-empty-note', 'Pick a pad to change how it sounds.'));",
  "        return panel;",
  "      }",
  "      var fields = el('div', 'st-pad-fields');",
  "      fields.appendChild(padSelect(track, bank, pad, 'mode', 'Mode',",
  "        [['oneshot', 'One shot'], ['gate', 'Gate']], pad.mode));",
  "      fields.appendChild(padRange(track, bank, pad, 'pitch', 'Pitch', -24, 24, 1, pad.pitch));",
  "      fields.appendChild(padRange(track, bank, pad, 'gain_db', 'Gain dB', -60, 12, 0.5, pad.gain_db));",
  "      fields.appendChild(padRange(track, bank, pad, 'pan', 'Pan', -1, 1, 0.05, pad.pan));",
  "      fields.appendChild(padRange(track, bank, pad, 'attack_ms', 'Attack ms', 0, 10000, 10, pad.attack_ms));",
  "      fields.appendChild(padRange(track, bank, pad, 'decay_ms', 'Decay ms', 0, 10000, 10, pad.decay_ms));",
  "      fields.appendChild(padRange(track, bank, pad, 'sustain', 'Sustain', 0, 1, 0.01, pad.sustain));",
  "      fields.appendChild(padRange(track, bank, pad, 'release_ms', 'Release ms', 0, 10000, 10, pad.release_ms));",
  "      var filter = pad.filter && typeof pad.filter === 'object' ? pad.filter : {};",
  "      fields.appendChild(padSelect(track, bank, pad, 'filter.type', 'Filter',",
