  "",
  "    // ---- the chop editor --------------------------------------------------",
  "",
  "    /** A decoded sample this page already holds, moved to the front of the cache. */",
  "    function cachedDecoded(id) {",
  "      var list = view.decodedSamples;",
  "      for (var at = 0; at < list.length; at += 1) {",
  "        if (list[at].sample_id !== id) continue;",
