  "",
  "    // The waveform: one column of peaks per pixel of the fixed viewBox, and one",
  "    // marker at every slice start.",
  "    function sampleWaveform(sample, slices) {",
  "      var svg = document.createElementNS(NS, 'svg');",
  "      svg.setAttribute('class', 'st-wave');",
  "      svg.setAttribute('viewBox', '0 0 ' + String(WAVE_W) + ' ' + String(WAVE_H));",
  "      svg.setAttribute('preserveAspectRatio', 'none');",
  "      svg.setAttribute('role', 'img');",
  "      svg.setAttribute('aria-label', 'Waveform of ' + String(sample.name) + ' with ' + String(slices.length) + ' slice markers');",
  "      var back = document.createElementNS(NS, 'rect');",
  "      back.setAttribute('width', String(WAVE_W));",
  "      back.setAttribute('height', String(WAVE_H));",
  "      back.setAttribute('fill', '#121417');",
  "      svg.appendChild(back);",
  "      var peaks = peaksOf(sample);",
  "      if (peaks && peaks.columns.length) {",
  "        var middle = WAVE_H / 2;",
  "        var parts = [];",
  "        for (var column = 0; column < peaks.columns.length; column += 1) {",
  "          var x = Math.round(((column + 0.5) / peaks.columns.length) * WAVE_W * 10) / 10;",
  "          var half = Math.max(0.5, (peaks.columns[column] || 0) * (middle - 2));",
  "          var top = Math.round((middle - half) * 10) / 10;",
  "          var bottom = Math.round((middle + half) * 10) / 10;",
  "          parts.push('M' + String(x) + ' ' + String(top) + 'L' + String(x) + ' ' + String(bottom));",
  "        }",
  "        var path = document.createElementNS(NS, 'path');",
  "        path.setAttribute('d', parts.join(' '));",
  "        path.setAttribute('fill', 'none');",
  "        path.setAttribute('stroke', '#B6D98A');",
  "        path.setAttribute('stroke-width', '1');",
  "        svg.appendChild(path);",
  "      }",
  "      var frames = Math.max(1, Math.round(Number(sample.frames) || (peaks ? peaks.frames : 0) || 1));",
  "      for (var at = 0; at < slices.length; at += 1) {",
  "        var start = clamp(Math.round(Number(slices[at].start_frame) || 0), 0, frames);",
  "        var x = Math.round((start / frames) * WAVE_W * 10) / 10;",
  "        var marker = document.createElementNS(NS, 'line');",
  "        marker.setAttribute('class', 'st-slice-marker');",
  "        marker.setAttribute('data-act', 'slice-marker');",
  "        marker.setAttribute('data-sample-id', String(sample.id));",
  "        marker.setAttribute('data-slice-id', String(slices[at].id));",
  "        marker.setAttribute('data-slice-at', String(at));",
  "        marker.setAttribute('x1', String(x));",
  "        marker.setAttribute('x2', String(x));",
  "        marker.setAttribute('y1', '0');",
  "        marker.setAttribute('y2', String(WAVE_H));",
  "        marker.setAttribute('stroke', '#F2A541');",
  "        marker.setAttribute('stroke-width', '3');",
  "        svg.appendChild(marker);",
  "      }",
  "      view.sliceWave = svg;",
  "      return svg;",
  "    }",
  "",
  "    // The chop editor: the selected pad's sample, its slices, the waveform and",
  "    // the three ways into a new slice set.",
  "    function chopEditor(snap, track, bank, pad, index) {",
  "      var box = el('div', 'st-chop');",
  "      var head = el('div', 'st-chop-head');",
  "      var sample = pad && pad.sample_id ? sampleOf(snap, pad.sample_id) : null;",
  "      if (!sample) {",
  "        head.appendChild(el('h3', 'st-sampler-sub', 'Sample'));",
  "        box.appendChild(head);",
  "        box.appendChild(el('p', 'st-empty-note', 'This pad holds no sound yet: import one, record one, or resample the output onto it.'));",
  "        return box;",
  "      }",
  "      var slices = slicesOfSample(snap, sample.id);",
  "      var played = sliceNumberPlayed(slices, pad.slice_id);",
  "      head.appendChild(el('h3', 'st-sampler-sub', 'Sample: ' + String(sample.name)));",
  "      head.appendChild(el('span', 'st-chop-meta',",
  "        (slices.length === 1 ? '1 slice' : String(slices.length) + ' slices')",
  "        + ' \u00b7 pad ' + (bank ? padLabel(bank, index) : String(index + 1))",
  "        + ' = ' + (played ? 'slice ' + String(played) : 'the whole sample')));",
  "      box.appendChild(head);",
  "",
  "      var tools = el('div', 'st-chop-tools');",
  "      tools.appendChild(button('st-btn st-small', 'Auto-chop by hits', {",
  "        'data-act': 'chop-hits',",
  "        'data-sample-id': String(sample.id),",
  "        title: 'Find the hits in this sound and give each one its own slice'",
  "      }));",
  "      var sensitivity = el('label', 'st-chop-sens');",
  "      var percent = Math.round(clamp(Number(view.chopSensitivity), 0, 1) * 100);",
  "      sensitivity.appendChild(el('span', 'st-pad-range-label', 'Sensitivity ' + String(percent) + '%'));",
  "      var range = el('input', 'st-pad-range-input');",
  "      range.type = 'range';",
  "      range.min = '0';",
  "      range.max = '1';",
  "      range.step = '0.05';",
  "      range.value = String(clamp(Number(view.chopSensitivity), 0, 1));",
  "      range.setAttribute('data-act', 'chop-sensitivity');",
  "      range.setAttribute('aria-label', 'How eagerly Auto-chop by hits finds hits');",
  "      sensitivity.appendChild(range);",
  "      tools.appendChild(sensitivity);",
  "      var gridLabel = el('label', 'st-pad-select');",
  "      gridLabel.appendChild(el('span', 'st-pad-range-label', 'Grid'));",
  "      var grid = el('select', 'st-select');",
  "      grid.setAttribute('data-act', 'chop-grid');",
  "      grid.setAttribute('data-sample-id', String(sample.id));",
  "      grid.setAttribute('aria-label', 'Chop this sound into equal slices');",
  "      var placeholder = el('option', '', 'Grid\u2026');",
  "      placeholder.value = '';",
  "      placeholder.selected = true;",
  "      grid.appendChild(placeholder);",
  "      var divisions = [2, 4, 8, 16];",
  "      for (var d = 0; d < divisions.length; d += 1) {",
  "        var option = el('option', '', String(divisions[d]) + ' slices');",
  "        option.value = String(divisions[d]);",
  "        grid.appendChild(option);",
  "      }",
  "      gridLabel.appendChild(grid);",
  "      tools.appendChild(gridLabel);",
  "      tools.appendChild(button('st-btn st-small', 'Assign slices to pads', {",
  "        'data-act': 'chop-assign',",
  "        'data-sample-id': String(sample.id),",
  "        title: 'Fill the pads from this one on, one slice each'",
  "      }));",
  "      box.appendChild(tools);",
  "      box.appendChild(sampleWaveform(sample, slices));",
  "      var readError = view.chopReadErrors[String(sample.id)];",
  "      if (readError) {",
