  "        readRow.appendChild(el('p', 'st-chop-error',",
  "          'This sound could not be read (' + String(readError) + ').'));",
  "        readRow.appendChild(button('st-btn st-small', 'Try again', {",
  "          'data-act': 'chop-retry', 'data-sample-id': String(sample.id),",
  "          title: 'Read this sound again'",
  "        }));",
  "        box.appendChild(readRow);",
  "      }",
  "      if (view.chopErrors[String(sample.id)]) {",
