  "      }",
  "      return box;",
  "    }",
  "",
  "    // ---- the steps --------------------------------------------------------",
  "",
  "    // The page of steps the clip's own playhead is in while the transport runs,",
  "    // or null when there is nothing to follow (stopped, or only one page).",
  "    function transportBeats() {",
  "      return ((view.position.bar - 1) * BEATS_PER_BAR)",
  "        + (view.position.beat - 1) + (view.position.sixteenth - 1) / 4;",
  "    }",
  "",
  "    /** The placement of one clip under a transport beat, or null. */",
  "    function placementForClipAt(snap, clip, beat) {",
  "      var placements = placementList(snap);",
  "      for (var at = 0; at < placements.length; at += 1) {",
  "        var placement = placements[at];",
  "        if (String(placement.clip_id) !== String(clip.id)) continue;",
  "        var start = Number(placement.start_bar) * BEATS_PER_BAR;",
  "        var end = start + Number(placement.bars) * BEATS_PER_BAR;",
  "        if (beat >= start && beat < end) return placement;",
  "      }",
  "      return null;",
  "    }",
  "",
  "    // Session: the beats since the clip launched. Arrangement: the beats since",
  "    // its placement started, plus that placement's offset. Either way the cycle",
  "    // is folded to the clip's own length before the page is chosen.",
  "    function pageForPlayhead(snap, clip) {",
  "      if (view.playing !== true || !clip) return null;",
  "      var steps = Math.round(Number(clip.length_steps) || 0);",
  "      var beats = Number(clip.step_beats) || 0.25;",
  "      if (!steps || steps <= STEP_PAGE) return null;",
  "      var cycle = steps * beats;",
  "      if (!(cycle > 0)) return null;",
  "      var played = transportBeats();",
  "      var since = played;",
  "      if (view.mode === ARRANGEMENT_VIEW) {",
  "        var placement = placementForClipAt(snap, clip, played);",
  "        if (placement) {",
  "          since = played - Number(placement.start_bar) * BEATS_PER_BAR",
  "            + (Number(placement.offset_beats) || 0);",
  "        }",
  "      } else {",
  "        var launch = view.launches[String(clip.track_id)];",
  "        if (launch && String(launch.clip_id) === String(clip.id) && Number.isFinite(Number(launch.bar))) {",
  "          since = played - Number(launch.bar) * BEATS_PER_BAR;",
  "        }",
  "      }",
