  "      var inLoop = ((at % steps) + steps) % steps;",
  "      return clamp(Math.floor(inLoop / STEP_PAGE), 0, STEP_PAGES - 1);",
  "    }",
  "",
  "    /** The step position a page starts on. */",
  "    function stepPageStart(page) {",
  "      return clamp(Math.round(Number(page) || 0), 0, STEP_PAGES - 1) * STEP_PAGE;",
  "    }",
  "",
  "    // The clip's own loop: they take the clip, and every pattern of it plays",
  "    // them. A length in step positions, a step length, and swing.",
  "    function loopRow(clip) {",
  "      var row = el('div', 'st-loop');",
  "      var length = Math.max(1, Math.round(Number(clip.length_steps) || STEP_PAGE));",
  "      var lengths = STEP_LENGTH_CHOICES.slice(0);",
  "      if (lengths.indexOf(length) < 0) {",
  "        lengths.push(length);",
  "        lengths.sort(function (a, b) { return a - b; });",
  "      }",
  "      var lengthLabel = el('label', 'st-pad-select');",
  "      lengthLabel.appendChild(el('span', 'st-pad-range-label', 'Length'));",
  "      var lengthSelect = el('select', 'st-select');",
  "      lengthSelect.setAttribute('data-act', 'pattern-length');",
  "      lengthSelect.setAttribute('data-clip-id', String(clip.id));",
  "      lengthSelect.setAttribute('aria-label', 'How many step positions the loop has');",
  "      for (var l = 0; l < lengths.length; l += 1) {",
  "        var lengthOption = el('option', '', String(lengths[l]) + ' steps');",
  "        lengthOption.value = String(lengths[l]);",
  "        if (lengths[l] === length) lengthOption.selected = true;",
  "        lengthSelect.appendChild(lengthOption);",
  "      }",
  "      lengthLabel.appendChild(lengthSelect);",
  "      row.appendChild(lengthLabel);",
  "",
  "      var beats = Number(clip.step_beats) || 0.25;",
  "      var beatLabel = el('label', 'st-pad-select');",
  "      beatLabel.appendChild(el('span', 'st-pad-range-label', 'Step'));",
  "      var beatSelect = el('select', 'st-select');",
  "      beatSelect.setAttribute('data-act', 'pattern-step-beats');",
  "      beatSelect.setAttribute('data-clip-id', String(clip.id));",
  "      beatSelect.setAttribute('aria-label', 'How long one step lasts');",
  "      var known = false;",
  "      for (var b = 0; b < STEP_BEAT_CHOICES.length; b += 1) {",
  "        var beatOption = el('option', '', STEP_BEAT_CHOICES[b][1]);",
  "        beatOption.value = STEP_BEAT_CHOICES[b][0];",
  "        if (Number(STEP_BEAT_CHOICES[b][0]) === beats) { beatOption.selected = true; known = true; }",
  "        beatSelect.appendChild(beatOption);",
  "      }",
  "      if (!known) {",
