  "        otherOption.value = String(beats);",
  "        otherOption.selected = true;",
  "        beatSelect.appendChild(otherOption);",
  "      }",
  "      beatLabel.appendChild(beatSelect);",
  "      row.appendChild(beatLabel);",
  "",
  "      var swingPercent = Math.round((Number(clip.swing) || 0) * 100);",
  "      var swingLabel = el('label', 'st-pad-range st-swing');",
  "      swingLabel.appendChild(el('span', 'st-pad-range-label', 'Swing ' + String(clamp(swingPercent, 0, 75)) + '%'));",
  "      var swing = el('input', 'st-pad-range-input');",
  "      swing.type = 'range';",
  "      swing.min = '0';",
  "      swing.max = '75';",
  "      swing.step = '1';",
  "      swing.value = String(clamp(swingPercent, 0, 75));",
  "      swing.setAttribute('data-act', 'pattern-swing');",
  "      swing.setAttribute('data-clip-id', String(clip.id));",
  "      swing.setAttribute('aria-label', 'How much the pattern swings');",
  "      swingLabel.appendChild(swing);",
  "      row.appendChild(swingLabel);",
  "      return row;",
  "    }",
  "",
  "    // The chain, as a row of pattern chips in the order they play, and the ways",
  "    // to change it: add the shown pattern to the end, move one, take one out.",
  "    // Every change is ONE chain.set carrying the whole new chain.",
  "    function chainEditor(snap, clip) {",
  "      var box = el('div', 'st-chain');",
  "      box.setAttribute('data-role', 'chain');",
  "      var patterns = patternsOfClip(snap, clip.id);",
  "      var chain = chainOf(clip, patterns);",
  "      box.appendChild(el('span', 'st-chain-label', 'Chain: '));",
  "      if (!chain.length) {",
  "        box.appendChild(el('span', 'st-chain-empty',",
  "          'plays pattern ' + String(patterns[0] ? patterns[0].name : 'A') + ' on repeat'));",
  "      }",
  "      for (var at = 0; at < chain.length; at += 1) {",
  "        if (at > 0) box.appendChild(el('span', 'st-chain-arrow', ' \u2192 '));",
  "        var pattern = patternById(snap, clip.id, chain[at]);",
  "        var name = String(pattern ? pattern.name : '?');",
  "        var chip = el('span', 'st-chain-chip');",
  "        var back = button('st-chain-btn', '\u2039', {",
  "          'data-act': 'chain-left', 'data-chain-at': String(at), 'data-chain-pattern-id': String(chain[at]),",
