  "          title: 'Move this pattern earlier in the chain'",
  "        });",
  "        back.disabled = at === 0;",
  "        chip.appendChild(back);",
  "        chip.appendChild(el('span', 'st-chain-name', name));",
  "        var forward = button('st-chain-btn', '\u203a', {",
  "          'data-act': 'chain-right', 'data-chain-at': String(at), 'data-chain-pattern-id': String(chain[at]),",
  "          'data-clip-id': String(clip.id),",
  "          'aria-label': 'Move pattern ' + name + ' later',",
  "          title: 'Move this pattern later in the chain'",
  "        });",
  "        forward.disabled = at === chain.length - 1;",
  "        chip.appendChild(forward);",
  "        chip.appendChild(button('st-chain-btn', '\u00d7', {",
  "          'data-act': 'chain-remove', 'data-chain-at': String(at), 'data-chain-pattern-id': String(chain[at]),",
  "          'data-clip-id': String(clip.id),",
  "          'aria-label': 'Take pattern ' + name + ' out of the chain',",
  "          title: 'Take this pattern out of the chain'",
  "        }));",
  "        box.appendChild(chip);",
  "      }",
  "      var shown = patternById(snap, clip.id, view.samplerPattern);",
  "      if (shown) {",
  "        var add = button('st-btn st-small st-chain-add', '+ ' + String(shown.name), {",
  "          'data-act': 'chain-add', 'data-pattern-id': String(shown.id), 'data-clip-id': String(clip.id),",
  "          title: 'Add the pattern being shown to the end of the chain'",
  "        });",
  "        add.disabled = chain.length >= STEP_PAGE * STEP_PAGES;",
  "        box.appendChild(add);",
  "      }",
  "      return box;",
  "    }",
  "",
  "    // A chain change: the whole new chain in one chain.set. A chip names both its",
  "    // index and the pattern it showed, so a chain that changed since the draw is",
  "    // redrawn instead of being changed at the wrong place.",
  "    function chainEdit(snap, clip, at, kind, patternId) {",
  "      var next = chainOf(clip, patternsOfClip(snap, clip.id));",
  "      var index = Number(at);",
  "      if (kind === 'add') {",
  "        if (!view.samplerPattern || next.length >= STEP_PAGE * STEP_PAGES) return;",
  "        next.push(String(view.samplerPattern));",
  "      } else if (kind === 'remove' || kind === 'left' || kind === 'right') {",
  "        if (!Number.isInteger(index) || index < 0 || index >= next.length) { render(); return; }",
  "        if (String(next[index]) !== String(patternId || '')) { render(); return; }",
  "        if (kind === 'remove') {",
  "          next.splice(index, 1);",
  "        } else if (kind === 'left') {",
  "          if (index <= 0) return;",
  "          var earlier = next[index - 1];",
