  "    }",
  "",
  "    // The step sequencer's panel: the patterns and the loop, the selected pad's",
  "    // lane of steps (sixteen a page) and the chain.",
  "    function stepsPanel(snap, clip, track, bank, index) {",
  "      var box = el('div', 'st-steps');",
