  "      view.samplerPage = clamp(Math.round(Number(view.samplerPage) || 0), 0, pages - 1);",
  "      view.stepLoop = { length: length, step_beats: Number(clip.step_beats) || 0.25 };",
  "",
  "      var tabs = el('div', 'st-pattern-tabs');",
  "      var patterns = patternsOfClip(snap, clip.id);",
  "      for (var i = 0; i < patterns.length; i += 1) {",
  "        var on = !!(pattern && String(patterns[i].id) === String(pattern.id));",
  "        var tab = button('st-toggle' + (on ? ' st-on' : ''), patterns[i].name, {",
  "          'data-act': 'pick-pattern',",
