  "        });",
  "        tabs.appendChild(tab);",
  "        if (on) {",
  "          tabs.appendChild(button('st-btn st-small', 'Rename', {",
  "            'data-act': 'rename-pattern',",
  "            'data-pattern-id': String(patterns[i].id),",
  "            'data-clip-id': String(clip.id),",
  "            title: 'Rename this pattern'",
  "          }));",
  "        }",
  "      }",
  "      tabs.appendChild(button('st-btn st-small', '+ Pattern', {",
  "        'data-act': 'add-pattern', 'data-clip-id': String(clip.id), title: 'Add a pattern to this clip'",
  "      }));",
  "      if (pattern) {",
  "        tabs.appendChild(button('st-btn st-small st-danger', 'Remove pattern', {",
  "          'data-act': 'remove-pattern', 'data-pattern-id': String(pattern.id), 'data-clip-id': String(clip.id),",
  "          title: 'Remove the pattern being shown, its steps and its place in the chain'",
  "        }));",
  "      }",
  "      box.appendChild(tabs);",
  "      box.appendChild(loopRow(clip));",
  "",
  "      var head = el('div', 'st-steps-head');",
